#!/usr/bin/env python3
# Dorama Avatar LipSync updater V0.6
# Запускать из корня репозитория dorama_lip:
#   python3 dorama_lip_update_v0_6.py

from pathlib import Path
import base64
import json
import sys

VERSION = "0.6"

FILES = json.loads(r"""{".github/workflows/build-apk.yml": "", "README_RU.txt": "", "app/build.gradle.kts": "", "app/src/main/AndroidManifest.xml": "", "app/src/main/java/com/dorama/avatar/MainActivity.kt": "", "app/src/main/java/com/dorama/avatar/WavUtils.kt": "", "app/src/main/res/layout/activity_main.xml": "", "app/src/main/res/values/styles.xml": "PHJlc291cmNlcz48c3R5bGUgbmFtZT0iVGhlbWUuRG9yYW1hQXZhdGFyIiBwYXJlbnQ9IlRoZW1lLk1hdGVyaWFsQ29tcG9uZW50cy5EYXlOaWdodC5Ob0FjdGlvbkJhciI+PGl0ZW0gbmFtZT0iYW5kcm9pZDpmb250RmFtaWx5Ij5zYW5zPC9pdGVtPjwvc3R5bGU+PC9yZXNvdXJjZXM+Cg==", "build.gradle.kts": "cGx1Z2lucyB7IGlkKCJjb20uYW5kcm9pZC5hcHBsaWNhdGlvbiIpIHZlcnNpb24gIjguNy4zIiBhcHBseSBmYWxzZTsgaWQoIm9yZy5qZXRicmFpbnMua290bGluLmFuZHJvaWQiKSB2ZXJzaW9uICIyLjAuMjEiIGFwcGx5IGZhbHNlIH0K", "gradle.properties": "b3JnLmdyYWRsZS5qdm1hcmdzPS1YbXgyMDQ4bSAtRGZpbGUuZW5jb2Rpbmc9VVRGLTgKYW5kcm9pZC51c2VBbmRyb2lkWD10cnVlCmtvdGxpbi5jb2RlLnN0eWxlPW9mZmljaWFsCg==", "settings.gradle.kts": ""}""")

root = Path.cwd()

# Защита от запуска в другом нашем проекте (например XTTSv2-Android)
if root.name != "dorama_lip":
    print(f"ОШИБКА: сейчас открыта папка {root}")
    print("Перейди в /workspaces/dorama_lip и запусти файл ещё раз.")
    sys.exit(2)

# Минимальная проверка структуры Android-проекта
required = [root / "app", root / "settings.gradle.kts"]
missing = [str(p) for p in required if not p.exists()]
if missing:
    print("ОШИБКА: не найден проект dorama_lip:", ", ".join(missing))
    sys.exit(3)

print("Dorama Avatar LipSync — применение V0.6")
print(f"Проект: {root}")

written = []
for rel, b64 in FILES.items():
    dst = root / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(b64)
    dst.write_bytes(data)
    written.append(rel)

# Удаляем старые ZIP-архивы обновлений, чтобы больше не путаться.
for old_zip in root.glob("DoramaAvatarLipSync_v0_*.zip"):
    try:
        old_zip.unlink()
        print(f"Удалён старый архив: {old_zip.name}")
    except OSError:
        pass

# Контрольные проверки — не даём случайно собрать старую версию.
checks = [
    ("app/build.gradle.kts", 'versionName = "0.6"'),
    ("app/src/main/res/layout/activity_main.xml", "Dorama Avatar • V0.6"),
    ("app/src/main/java/com/dorama/avatar/MainActivity.kt", "V0.6 ГОТОВА"),
    (".github/workflows/build-apk.yml", "v0.6-debug"),
]

failed = []
for rel, marker in checks:
    text = (root / rel).read_text(encoding="utf-8")
    if marker not in text:
        failed.append(f"{rel} -> {marker}")

if failed:
    print("\nОШИБКА ПРОВЕРКИ V0.6:")
    for item in failed:
        print(" -", item)
    sys.exit(4)

print(f"\n✓ V0.6 применена. Обновлено файлов: {len(written)}")
print("✓ versionName = 0.6")
print("✓ интерфейс = V0.6")
print("✓ MainActivity = V0.6")
print("✓ GitHub Actions artifact = v0.6-debug")
print("\nТеперь выполни:")
print("  git status")
print("  git add .")
print('  git commit -m "Add Dorama Avatar LipSync v0.6"')
print("  git push")
